public static CustTable findCustomer(AccountNum _accountNum)
{
    CustTable custTable;

    select firstOnly custTable
    where custTable.AccountNum == _accountNum;

    return custTable;
}

public static boolean createCustomer(CustTable _custTable)
{
    boolean success = false;

    if (!JSZCustomerValidation::validateCustomer(_custTable))
    {
        return false;
    }

    ttsbegin;

    try
    {
        _custTable.insert();

        ttscommit;

        success = true;
    }
    catch (Exception::Error)
    {
        ttsabort;

        error("@JSZCustomer:CustomerCreateError");
    }

    return success;
}

